// build-part-mocs.mjs — regenerate ONLY the four part-level MOCs.
//
//   node build/build-part-mocs.mjs            # all parts
//   node build/build-part-mocs.mjs --part 01_Mathematics
//
// Why this exists: the part MOCs are generated by `renderPartMOC` (expand.mjs), but the only
// script that writes them is `build-stubs.mjs`, which ALSO rewrites all 408 topic notes as
// empty stubs. That is safe only immediately before `build-notes.mjs`. When all you have
// changed is something the part MOC renders — e.g. a `PART_NOTES` review-sheet link — running
// the full stub pass is a needless risk to 408 rendered notes. This script touches exactly
// four files and nothing else.
//
// It writes no topic note and no area MOC.

import { writeFileSync } from 'node:fs';
import { AREAS, AREA_NAMES, VAULT } from './vault.mjs';
import { renderPartMOC } from './expand.mjs';

const wantIdx = process.argv.indexOf('--part');
const only = wantIdx !== -1 ? process.argv[wantIdx + 1] : null;

if (only && !AREA_NAMES[only]) {
  console.error(`unknown part: ${only}`);
  console.error(`known parts: ${Object.keys(AREA_NAMES).join(', ')}`);
  process.exitCode = 1;
} else {
  let n = 0;
  for (const part of Object.keys(AREA_NAMES)) {
    if (only && part !== only) continue;
    const areas = AREAS.filter((a) => a.part === part);
    const name = part.replace(/^\d+_/, '');
    const path = `${VAULT}/${part}/_MOC_${name}.md`;
    writeFileSync(path, renderPartMOC(part, AREA_NAMES[part], areas), 'utf8');
    console.log(`wrote ${path}  (${areas.length} areas)`);
    n++;
  }
  console.log(`part MOCs written: ${n}`);
}
